  [DependencyUnit <String>]: Unit type for the aggregation thresholds. Required when aggregationType is MinHealthy or MaxNotHealthy.
  [ResourceHealthEnabled <String>]: Whether to automatically add a signal for the Azure resource's availability state from Azure Resource Health. Defaults to Enabled.
